const ALIASES: Record<string, string> = {
  "google-calendar": 'googlecalendar',
  "google-drive": 'googledrive',
  "bigquery": 'googlebigquery',
  "tiktok-ads": 'tiktok',
  "hugging-face": 'huggingface',
  "gcalendar": 'googlecalendar',
  "gdrive": 'googledrive',
  "gmail_imap": 'gmail',
  "google_tasks": 'googletasks',
  "github_notifications": 'github',
  "garmin_connect": 'garmin',
  "news_rss": 'rss',
  "apple_music": 'applemusic',
  "apple_calendar": 'apple',
  "apple_contacts": 'apple',
  "apple_health": 'apple',
  "apple_notes": 'apple',
  "google calendar": 'googlecalendar',
  "google drive": 'googledrive',
  "google bigquery": 'googlebigquery',
  "hugging face": 'huggingface',
  "google tasks": 'googletasks',
  "apple music": 'applemusic',
  "gemini": 'googlegemini',
  "claude code": 'claude',
  "garmin connect": 'garmin',
};

function key(text: string): string {
  return text
    .toLowerCase()
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    .trim();
}

/** The brand of a connector, MCP server, CLI or tool, by id or by name. */
export function brandFor(...names: Array<string | undefined | null>): Brand | null {
  for (const raw of names) {
    if (!raw) continue;
    const k = key(raw);
    const slug = ALIASES[k] ?? (BRANDS[k] ? k : BRANDS[k.replace(/[^a-z0-9]/g, '')] ? k.replace(/[^a-z0-9]/g, '') : '');
    if (slug && BRANDS[slug]) return BRANDS[slug];
    // «mcp__github__…», «gmail_send», «Google Drive (MCP)»: the first known word.
    for (const part of k.split(/[^a-z0-9]+/)) {
      const hit = ALIASES[part] ?? (BRANDS[part] ? part : '');
      if (hit && part.length > 2) return BRANDS[hit];
    }
  }
  return null;
}

/** Light brand colours get a dark tile so the logo stays visible. */
export function isLight(hex: string): boolean {
  const n = parseInt(hex, 16);
  const [r, g, b] = [(n >> 16) & 255, (n >> 8) & 255, n & 255];
  return 0.2126 * r + 0.7152 * g + 0.0722 * b > 200;
}

const TITLES = Object.entries(BRANDS)
  .filter(([slug, b]) => b.title.length > 3 && slug !== 'google')
  .map(([slug, b]) => ({ slug, re: new RegExp(`(^|[^\\p{L}\\p{N}])${b.title.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}(?![\\p{L}\\p{N}])`, 'u') }));

/** The services a sentence names by their written name («Busca en Gmail…»):
 * case-sensitive, so everyday words («box», «zoom») never turn into logos. */
export function brandsIn(text: string, max = 3): Brand[] {
  const out: Brand[] = [];
  for (const t of TITLES) {
    if (t.re.test(text)) out.push(BRANDS[t.slug]);
    if (out.length >= max) break;
  }
  return out;
}
